"""Snap span times to a fixed step and label the results."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span


def check_step(step: int) -> None:
    """Steps are whole minutes dividing an hour evenly."""
    if not isinstance(step, int) or step <= 0 or 60 % step:
        raise ValueError(f"bad rounding step: {step!r}")


def snap_minute(value: int, step: int) -> int:
    """Nearest multiple of step. Halfway points go up."""
    return (2 * value + step) // (2 * step) * step


def snap_span(span: Span, step: int) -> Span:
    """Round both ends. Raises if the span collapses."""
    return Span(
        snap_minute(span.start, step),
        snap_minute(span.end, step)
    )


def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    hours, extra = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {extra}m)"


# ---
def round_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Round each span to step minutes and label it."""
    check_step(step)
    return [
        span_label(snap_span(item, step)) for item in spans
    ]

