# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_labels


class RoundLabelTests(unittest.TestCase):
    def test_already_on_step(self):
        spans = [Span(540, 1035)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        spans = [Span(542, 1030)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_goes_up(self):
        spans = [Span(555, 615)]
        self.assertEqual(
            round_labels(spans, 30), ["09:30-10:30 (1h 0m)"]
        )

    def test_many_spans_in_order(self):
        spans = [Span(60, 125), Span(0, 1440)]
        self.assertEqual(
            round_labels(spans, 30),
            ["01:00-02:00 (1h 0m)", "00:00-24:00 (24h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 90, 15.0):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels([Span(0, 60)], step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_labels([Span(61, 64)], 15)


if __name__ == "__main__":
    unittest.main()
